#include <iostream>
#include <vector>

int main() {
    // Initialize a simple integer with uniform initialization
    int ling_ling{42};  // Safe initialization; compiler checks for narrowing

    // Initialize a vector (common in real-world data processing)
    std::vector<int> numbers{10, 20, 30, 40};

    // Output the values
    std::cout << "ling_ling: " << ling_ling << std::endl;
    for (const auto& num : numbers) {
        std::cout << num << " ";  // Iterating over initialized container
    }
    std::cout << std::endl;

    return 0;
}
